    rcases x : leaves e with ( _ | ⟨ a, _ | ⟨ b, l ⟩ ⟩ ) <;> rcases y : leaves k with ( _ | ⟨ c, _ | ⟨ d, m ⟩ ⟩ ) <;> simp_all +decide;
    · exact absurd ( leaves_length_pos e ) ( by simp +decide [ x ] );
    · have h_eval : evalDigitExpr e = (d₁ : ℤ) ∨ evalDigitExpr e = -(d₁ : ℤ) := by
        grind +suggestions
      have h_eval' : evalDigitExpr k = (d₂ : ℤ) ∨ evalDigitExpr k = -(d₂ : ℤ) := by
        grind +suggestions;
      unfold possibleValuesTwo; simp +decide [ * ] ;
      erw [ show evalDigitExpr ( e.pow k ) = ( evalDigitExpr e ) ^ ( evalDigitExpr k |> Int.toNat ) from rfl ] ; rcases h_eval with ha | ha <;> rcases h_eval' with hb | hb <;> simp +decide [ ha, hb ] ;
    · have h_contra : ∀ e : DigitExpr, leaves e = [] → False := by
        intro e he; induction e <;> simp_all +decide [ leaves ] ;
      exact False.elim <| h_contra k y

theorem not_mem_25 : (25 : ℤ) ∉ possibleValuesTwo 2 5 := by decide

theorem not_isOrderlyFriedman_25 : ¬ IsOrderlyFriedman 25 := by
  rintro ⟨e, heval, hleaves⟩
  have hd : digitsOfNat 25 = [2, 5] := by decide
  rw [hd] at hleaves
  have hmem := two_leaf_eval e hleaves
  rw [heval] at hmem
  have hcast : ((25 : ℕ) : ℤ) = (25 : ℤ) := by norm_num
  rw [hcast] at hmem
  exact not_mem_25 hmem

